import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  random,
} from '../remotionShim';
import { Circle, Rect } from "@remotion/shapes";

// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---



export type FriendshipBannerProps = Record<string, any>;

// --- Sub-components ---

const DottedPattern: React.FC<{
  color: string;
  rows?: number;
  cols?: number;
  spacing?: number;
  radius?: number;
  style?: React.CSSProperties;
}> = ({ color, rows = 5, cols = 5, spacing = 20, radius = 3, style }) => {
  const dots = [];
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      dots.push(
        <Circle
          key={`${i}-${j}`}
          radius={radius}
          fill={color}
          style={{
            position: "absolute",
            top: i * spacing,
            left: j * spacing,
          }}
        />
      );
    }
  }
  return <div style={{ position: "absolute", ...style }}>{dots}</div>;
};

const AnimatedText: React.FC<{
  text: string;
  color: string;
  fontSize: number;
  fontFamily: string;
  delayStart: number;
  lineHeight?: number;
  style?: React.CSSProperties;
}> = ({ text, color, fontSize, fontFamily, delayStart, lineHeight = 1, style }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "row",
        gap: fontSize * 0.1,
        ...style,
      }}
    >
      {text.split("").map((char, index) => {
        const delay = delayStart + index * 2;
        
        const spr = spring({
          frame: frame - delay,
          fps,
          config: { damping: 12, stiffness: 200 },
        });

        const translateY = interpolate(spr, [0, 1], [fontSize, 0]);
        const opacity = interpolate(spr, [0, 1], [0, 1]);
        const scale = interpolate(spr, [0, 1], [0.5, 1]);

        return (
          <div
            key={index}
            style={{
              fontFamily,
              color,
              fontSize,
              fontWeight: 900,
              lineHeight,
              transform: `translateY(${translateY}px) scale(${scale})`,
              opacity,
              display: "inline-block",
              textShadow: "4px 4px 0px rgba(0,0,0,0.1)",
            }}
          >
            {char === " " ? "\u00A0" : char}
          </div>
        );
      })}
    </div>
  );
};

const FloatingIcon: React.FC<{
  emoji: string;
  x: number;
  y: number;
  size: number;
  delay: number;
}> = ({ emoji, x, y, size, delay }) => {
  const frame = useCurrentFrame();
  const offset = Math.sin((frame + delay) / 20) * 10;
  
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y + offset,
        fontSize: size,
      }}
    >
      {emoji}
    </div>
  );
};

